const rows = Array.isArray($json) ? $json : [$json];
const lead = rows[0];
if (!lead || !lead.id) return [];
const systemPrompt = `You are a senior web designer at a professional web studio. You build a complete, production-ready, single-page marketing website for a small business from a short brief.

Output rules (CRITICAL):
- Return ONE complete HTML document and NOTHING else. Start at <!DOCTYPE html> and end at </html>. No markdown code fences, no explanation, no preamble.
- Everything inline in that one file: a single <style> block in <head>. No external build step, no JS frameworks. A small amount of vanilla JS is fine but the site must work with JS disabled.
- You MAY use Google Fonts via <link> and may use CSS only. No other external assets except Unsplash/picsum-style placeholder image URLs if you need photography.
- Mobile-first and fully responsive. Must look great at 375px and 1280px.
- Accessible: semantic landmarks, alt text, sufficient color contrast, focus states.

Required sections, in order:
1. Sticky header with the business name/logo text + anchor nav.
2. Hero: headline, one-sentence subhead, primary call-to-action button.
3. About: 2-3 short paragraphs in the business's voice.
4. Services: 3-6 cards. Include prices ONLY if the brief implies them; otherwise describe the offering without inventing prices.
5. A trust/why-us strip.
6. Contact: business hours if implied, tel link if phone present, mailto link, and simple contact form action="#". Embed a Google Maps iframe ONLY if a real address is given.
7. Footer with copyright + business name.

Theming contract (REQUIRED): define ALL colors and fonts as CSS custom properties on :root using EXACTLY these names and reference them everywhere: --c-bg, --c-surface, --c-text, --c-heading, --c-muted, --c-border, --c-accent, --c-accent-contrast, --font-heading, --font-body, --radius.

Design rules:
- Match requested style/vibe in palette, type, spacing, imagery mood.
- Avoid generic AI slop: no purple SaaS gradients, no emoji icon cards, no cookie-cutter equal-card page.
- Use real, specific copy derived from the brief.
- Give it a polished local-business feel that could sell hosting.`;
const userPrompt = `Business name: ${lead.business_name || ''}
What the business does: ${lead.business_description || ''}
Style / vibe: ${lead.style_vibe || 'choose the most fitting style for this business'}
Contact email: ${lead.contact_email || ''}
Contact phone: ${lead.contact_phone || ''}

Build the complete single-file website now. Output only the HTML.`;
return [{ json: { lead, anthropicPayload: { model: 'claude-sonnet-4-6', max_tokens: 16000, system: systemPrompt, messages: [{ role: 'user', content: userPrompt }] } } }];

const lead = $('Prepare Anthropic payload').first().json.lead;
const content = $json.content || [];
let html = '';
if (Array.isArray(content)) {
  html = content.map(part => part.text || '').join('');
} else if (typeof content === 'string') {
  html = content;
}
html = html.replace(/^\s*```[a-zA-Z]*\s*\n/, '').replace(/\n```\s*$/, '').trim();
if (!html.includes('<html') || !html.toLowerCase().startsWith('<!doctype html')) {
  throw new Error('Anthropic output did not look like a complete HTML document');
}
return [{ json: { lead, html } }];
